-- ============================================================
-- STEP 2: Create the transfer_parts function
-- ============================================================
CREATE OR REPLACE FUNCTION transfer_parts(
    source_inventory_id   INTEGER,
    target_inventory_id   INTEGER,
    part_to_transfer_num  VARCHAR,
    color_to_transfer_id  INTEGER,
    quantity_to_transfer  INTEGER,
    transfer_reason       VARCHAR DEFAULT 'manual_transfer'
)
RETURNS TEXT
LANGUAGE plpgsql
AS $$
DECLARE
    -- Source record fields
    v_source_quantity   INTEGER;
    v_source_is_spare   BOOLEAN;

    -- Target record fields
    v_target_quantity   INTEGER;

    -- Existence flags
    v_source_inv_exists BOOLEAN;
    v_target_inv_exists BOOLEAN;
    v_part_exists       BOOLEAN;
    v_color_exists      BOOLEAN;

    -- Return message
    v_result_msg        TEXT;

    -- Error capture
    v_error_msg         TEXT;
BEGIN
    -- ===========================================================
    -- VALIDATION A: BASIC PARAMETER CHECKS
    -- ===========================================================

    -- Prevent self-transfers immediately (no DB round-trip needed)
    IF source_inventory_id = target_inventory_id THEN
        v_error_msg := 'Self-transfer not allowed: source and target inventory IDs are identical (' 
                       || source_inventory_id || ').';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason, 'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- ===========================================================
    -- VALIDATION B: BUSINESS RULE — QUANTITY BOUNDS
    -- ===========================================================

    IF quantity_to_transfer < 1 THEN
        v_error_msg := 'Invalid transfer quantity: ' || quantity_to_transfer 
                       || '. Minimum transfer quantity is 1.';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason, 'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    IF quantity_to_transfer > 500 THEN
        v_error_msg := 'Transfer quantity ' || quantity_to_transfer 
                       || ' exceeds the maximum allowed limit of 500 parts per operation.';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason, 'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- ===========================================================
    -- VALIDATION A: ENTITY EXISTENCE CHECKS
    -- ===========================================================

    -- Check source inventory exists
    SELECT EXISTS(SELECT 1 FROM lego_inventories WHERE id = source_inventory_id)
    INTO v_source_inv_exists;

    IF NOT v_source_inv_exists THEN
        v_error_msg := 'Source inventory ID ' || source_inventory_id || ' does not exist.';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason, 'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- Check target inventory exists
    SELECT EXISTS(SELECT 1 FROM lego_inventories WHERE id = target_inventory_id)
    INTO v_target_inv_exists;

    IF NOT v_target_inv_exists THEN
        v_error_msg := 'Target inventory ID ' || target_inventory_id || ' does not exist.';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason, 'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- Check part exists in lego_parts catalogue
    SELECT EXISTS(SELECT 1 FROM lego_parts WHERE part_num = part_to_transfer_num)
    INTO v_part_exists;

    IF NOT v_part_exists THEN
        v_error_msg := 'Part number "' || part_to_transfer_num || '" does not exist in the parts catalogue.';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason, 'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- Check color exists in lego_colors catalogue
    SELECT EXISTS(SELECT 1 FROM lego_colors WHERE id = color_to_transfer_id)
    INTO v_color_exists;

    IF NOT v_color_exists THEN
        v_error_msg := 'Color ID ' || color_to_transfer_id || ' does not exist in the colors catalogue.';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason, 'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- ===========================================================
    -- STEP A: LOCK SOURCE + TARGET ROWS & VALIDATE QUANTITY
    -- (SELECT … FOR UPDATE prevents race conditions)
    -- ===========================================================

    -- Lock the source inventory_parts row and read its quantity
    SELECT quantity, is_spare
    INTO   v_source_quantity, v_source_is_spare
    FROM   lego_inventory_parts
    WHERE  inventory_id = source_inventory_id
      AND  part_num     = part_to_transfer_num
      AND  color_id     = color_to_transfer_id
    FOR UPDATE;

    -- Source row must exist (part must actually be in source inventory)
    IF NOT FOUND THEN
        v_error_msg := 'Part "' || part_to_transfer_num 
                       || '" with color_id ' || color_to_transfer_id 
                       || ' was not found in source inventory ' || source_inventory_id || '.';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason, 'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- Sufficient quantity check
    IF v_source_quantity < quantity_to_transfer THEN
        v_error_msg := 'Insufficient quantity in source inventory ' || source_inventory_id 
                       || '. Requested: ' || quantity_to_transfer 
                       || ', Available: ' || v_source_quantity 
                       || ' (part: ' || part_to_transfer_num 
                       || ', color_id: ' || color_to_transfer_id || ').';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason, 'failed', v_error_msg
        );
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- Lock target row if it exists (no error if missing — we will INSERT instead)
    SELECT quantity
    INTO   v_target_quantity
    FROM   lego_inventory_parts
    WHERE  inventory_id = target_inventory_id
      AND  part_num     = part_to_transfer_num
      AND  color_id     = color_to_transfer_id
    FOR UPDATE;

    -- ===========================================================
    -- STEP B: UPDATE SOURCE INVENTORY
    -- ===========================================================

    IF v_source_quantity = quantity_to_transfer THEN
        -- Quantity becomes zero → delete the row entirely
        DELETE FROM lego_inventory_parts
        WHERE  inventory_id = source_inventory_id
          AND  part_num     = part_to_transfer_num
          AND  color_id     = color_to_transfer_id;
    ELSE
        -- Decrease quantity, keep is_spare flag intact
        UPDATE lego_inventory_parts
        SET    quantity = quantity - quantity_to_transfer
        WHERE  inventory_id = source_inventory_id
          AND  part_num     = part_to_transfer_num
          AND  color_id     = color_to_transfer_id;
    END IF;

    -- ===========================================================
    -- STEP C: UPDATE OR INSERT TARGET INVENTORY
    -- ===========================================================

    IF FOUND AND v_target_quantity IS NOT NULL THEN
        -- Target row already exists → increment quantity
        UPDATE lego_inventory_parts
        SET    quantity = quantity + quantity_to_transfer
        WHERE  inventory_id = target_inventory_id
          AND  part_num     = part_to_transfer_num
          AND  color_id     = color_to_transfer_id;
    ELSE
        -- Target row does not exist → insert new record
        -- Preserve the is_spare flag from the source record
        INSERT INTO lego_inventory_parts (inventory_id, part_num, color_id, quantity, is_spare)
        VALUES (target_inventory_id, part_to_transfer_num, color_to_transfer_id,
                quantity_to_transfer, v_source_is_spare);
    END IF;

    -- ===========================================================
    -- STEP D: AUDIT LOG — SUCCESS
    -- ===========================================================

    INSERT INTO inventory_transfer_log (
        source_inventory_id, target_inventory_id, part_num, color_id,
        quantity_transferred, transfer_reason, transfer_status, error_message
    ) VALUES (
        source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id,
        quantity_to_transfer, transfer_reason, 'success', NULL
    );

    -- ===========================================================
    -- RETURN SUCCESS MESSAGE
    -- ===========================================================

    v_result_msg := 'Successfully transferred ' || quantity_to_transfer 
                    || ' parts (' || part_to_transfer_num 
                    || ', color_id: ' || color_to_transfer_id 
                    || ') from inventory ' || source_inventory_id 
                    || ' to inventory ' || target_inventory_id 
                    || '. Reason: ' || transfer_reason;

    RETURN v_result_msg;

EXCEPTION
    -- Re-raise any RAISE EXCEPTION that already inserted the audit log row
    WHEN OTHERS THEN
        RAISE;
END;
$$;
"}

